// =============================================================================
// SIMULADOR DO CLP S7-1200 (para desenvolver sem a bancada)
// Ativo somente se a variável de ambiente SIMULATE=true.
// Gera um objeto com OS MESMOS NOMES de variáveis que o nó "s7 in" (modo "all")
// produz, para que o restante do fluxo seja idêntico com ou sem CLP.
// Comandos manuais: msg.topic = "sim_cmd", msg.payload = START | STOP | EMERGENCY | RESET
// =============================================================================
if (env.get("SIMULATE") !== "true") { return null; }

let sim = context.get("sim") || { running: false, emergency: false, pulse: null, pulseTicks: 0 };

if (msg.topic === "sim_cmd") {
    const cmd = String(msg.payload || "").toUpperCase();
    if (cmd === "START" && !sim.emergency) { sim.running = true;  sim.pulse = "START"; }
    if (cmd === "STOP")                    { sim.running = false; sim.pulse = "STOP"; }
    if (cmd === "EMERGENCY")               { sim.running = false; sim.emergency = true; }
    if (cmd === "RESET")                   { sim.emergency = false; }
    sim.pulseTicks = 3;               // botão "fica apertado" por ~300 ms
    context.set("sim", sim);
    node.status({ fill: "blue", shape: "ring", text: "SIM: " + cmd });
    return null;                      // a próxima leitura (tick) já reflete o novo estado
}

// ---- tick de leitura (a cada 100 ms) ----
const green = sim.pulseTicks > 0 && sim.pulse === "START";
const red   = sim.pulseTicks > 0 && sim.pulse === "STOP";
if (sim.pulseTicks > 0) { sim.pulseTicks--; }
context.set("sim", sim);

const belts = sim.running && !sim.emergency;
const station = (prefix) => ({
    [prefix + "_segurancaOK"]: !sim.emergency,
    [prefix + "_chaveAutomatico"]: true,
    [prefix + "_botaoVerde"]: green,
    [prefix + "_botaoVermelho"]: red,
    [prefix + "_esteira1"]: belts,
    [prefix + "_esteira2"]: belts
});

msg.payload = Object.assign(
    {
        emergencia: sim.emergency,
        emergenciaAtivada: sim.emergency,
        ocupado: belts,
        aguardando: !belts,
        manual: false,
        comutadorAutomatico: true,
        condicaoIniciar: !sim.emergency,
        numeroOP: 1
    },
    station("processo"), station("montagem"), station("expedicao")
);
msg.source = "SIMULATOR";
node.status({ fill: sim.emergency ? "red" : (belts ? "green" : "grey"), shape: "dot",
              text: sim.emergency ? "SIM: EMERGÊNCIA" : (belts ? "SIM: RODANDO" : "SIM: PARADO") });
return msg;

// =============================================================================
// NORMALIZAÇÃO: snapshot bruto do CLP  ->  JSON padrão de telemetria (Grupo 1)
// Entrada : msg.payload = { emergencia: bool, processo_botaoVerde: bool, ... }
// Saída   : msg.payload = objeto de telemetria (sem msg_id; é adicionado depois)
// ATENÇÃO : a regra de "machine_state" abaixo é uma HIPÓTESE a validar na
//           bancada (ver docs/mapeamento-clp.md).
// =============================================================================
const simulate = env.get("SIMULATE") === "true";
const source = msg.source || "PLC";
// Em modo simulação, ignora leituras vindas do CLP real (e vice-versa).
if (simulate && source !== "SIMULATOR") { return null; }
if (!simulate && source === "SIMULATOR") { return null; }

const r = msg.payload || {};
const b = (k) => r[k] === true;                       // undefined/null -> false
const MACHINE_ID = env.get("MACHINE_ID") || "SMART-40-PLANTA-N2";
const NOMINAL = parseFloat(env.get("BELT_NOMINAL_SPEED")); // NaN se não definido

const st = (p) => ({
    seguranca_ok: b(p + "_segurancaOK"),
    automatico:   b(p + "_chaveAutomatico"),
    botao_verde:  b(p + "_botaoVerde"),
    botao_vermelho: b(p + "_botaoVermelho"),
    esteira1:     b(p + "_esteira1"),
    esteira2:     b(p + "_esteira2")
});
const stations = { processo: st("processo"), montagem: st("montagem"), expedicao: st("expedicao") };
const list = Object.values(stations);

const startPressed = list.some(s => s.botao_verde);
const stopPressed  = list.some(s => s.botao_vermelho);
const emergency    = b("emergencia") || b("emergenciaAtivada");
const beltRunning  = list.some(s => s.esteira1 || s.esteira2);
const safetyFault  = list.some(s => !s.seguranca_ok);

// Mapeado para o ENUM machine_state do banco (STOPPED, RUNNING, PAUSED, EMERGENCY, ALARM)
let state;
if (emergency)                       state = "EMERGENCY";
else if (safetyFault)                state = "ALARM";
else if (beltRunning || b("ocupado")) state = "RUNNING";
else if (b("manual"))                state = "PAUSED";
else                                 state = "STOPPED";

// Não há registrador de velocidade no mapa atual do CLP: as esteiras são ON/OFF.
let beltSpeed = 0, speedSource = "PLC_DIGITAL";
if (beltRunning) {
    if (isNaN(NOMINAL)) { beltSpeed = null; speedSource = "UNAVAILABLE"; }
    else                { beltSpeed = NOMINAL; speedSource = "NOMINAL_CONFIG"; }
}

msg.payload = {
    machine_id: MACHINE_ID,
    timestamp: new Date().toISOString(),
    source: source,
    machine_state: state,
    belt_running: beltRunning,
    belt_speed: beltSpeed,
    belt_speed_source: speedSource,
    buttons: {
        start_pressed: startPressed,
        stop_pressed: stopPressed,
        emergency_pressed: emergency,
        reset_pressed: false            // não há botão Reset no mapa do CLP (pendente)
    },
    stations: stations,
    flags: {
        ocupado: b("ocupado"),
        aguardando: b("aguardando"),
        manual: b("manual"),
        comutador_automatico: b("comutadorAutomatico"),
        condicao_iniciar: b("condicaoIniciar")
    },
    numero_op: (typeof r.numeroOP === "number") ? r.numeroOP : null
};
return msg;

// =============================================================================
// REPORT-BY-EXCEPTION: lê a cada 100 ms, mas só publica quando algo muda
// (+ um HEARTBEAT periódico). Protege HiveMQ/Neon de milhares de linhas iguais.
// Também carimba msg_id (chave de idempotência) e seq.
// =============================================================================
const HEARTBEAT_MS = Number(env.get("HEARTBEAT_MS") || 5000);
const p = msg.payload;

// Assinatura do estado SEM o timestamp (senão tudo seria "mudança")
const sig = JSON.stringify([p.machine_state, p.belt_running, p.belt_speed, p.buttons,
                            p.stations, p.flags, p.numero_op]);
const now = Date.now();
const lastSig  = context.get("lastSig");
const lastSent = context.get("lastSent") || 0;

let event;
if (sig !== lastSig)                  event = "STATE_CHANGE";
else if (now - lastSent >= HEARTBEAT_MS) event = "HEARTBEAT";
else return null;                      // nada novo: descarta esta leitura

const seq = (context.get("seq") || 0) + 1;
context.set("seq", seq);
context.set("lastSig", sig);
context.set("lastSent", now);

p.event = event;
p.seq = seq;
// ID único e estável: o iot-service usa isto para NÃO duplicar após reconexão
p.msg_id = p.machine_id + "-" + now + "-" + seq + "-" + Math.random().toString(36).slice(2, 8);
p.buffered = false;

flow.set("last_telemetry", p);         // usado pelo endpoint local GET /edge/status
msg.topic = env.get("MQTT_TOPIC_DATA") || "industria40/telemetry/data";
return msg;

// =============================================================================
// STORE-AND-FORWARD (buffer offline)
// - Online e fila vazia  -> envia direto para o "mqtt out" (QoS 1)
// - Offline (ou fila com pendências) -> guarda na fila persistente (contexto "file")
// - Ao reconectar -> descarrega a fila em lotes, em ordem, marcando buffered=true
// Entradas aceitas:
//   * telemetria (msg.payload objeto)
//   * msg.status  (vindo do nó "status" que observa o "mqtt out")
//   * msg.topic "__force_offline__" / "__force_online__" (teste sem tirar o cabo)
// =============================================================================
const STORE = env.get("BUFFER_STORE") || "file";
const MAX   = Number(env.get("BUFFER_MAX") || 50000);
const BATCH = Number(env.get("BUFFER_BATCH") || 100);
const BATCH_INTERVAL_MS = 500;

function isOnline() {
    return flow.get("mqtt_online") === true && flow.get("force_offline") !== true;
}
function getQ() { return flow.get("sf_queue", STORE) || []; }
function setQ(q) { flow.set("sf_queue", q, STORE); }
function showStatus() {
    const n = getQ().length;
    node.status(isOnline()
        ? { fill: n ? "yellow" : "green", shape: "dot", text: n ? "online - descarregando " + n : "online" }
        : { fill: "red", shape: "ring", text: "OFFLINE - " + n + " msg no buffer" });
}
function flushChunk() {
    if (!isOnline()) { context.set("flushing", false); showStatus(); return; }
    const q = getQ();
    if (q.length === 0) { context.set("flushing", false); showStatus(); return; }
    const chunk = q.splice(0, BATCH);
    setQ(q);
    chunk.forEach(function (item) {
        item.payload.buffered = true;
        node.send({ topic: item.topic, payload: item.payload, qos: 1, retain: false });
    });
    showStatus();
    setTimeout(flushChunk, BATCH_INTERVAL_MS);
}
function startFlush() {
    if (context.get("flushing") === true) return;
    context.set("flushing", true);
    flushChunk();
}

// ---- 1) Mudança de status da conexão MQTT ----
if (msg.status) {
    const wasOnline = isOnline();
    flow.set("mqtt_online", msg.status.fill === "green");
    if (!wasOnline && isOnline()) {
        node.warn("MQTT reconectado. Itens no buffer: " + getQ().length);
        startFlush();
    }
    showStatus();
    return null;
}
// ---- 2) Comandos de teste ----
if (msg.topic === "__force_offline__") { flow.set("force_offline", true);  showStatus(); return null; }
if (msg.topic === "__force_online__")  { flow.set("force_offline", false); startFlush(); showStatus(); return null; }

// ---- 3) Telemetria ----
const item = { topic: msg.topic, payload: msg.payload };
const q = getQ();
if (isOnline() && q.length === 0) {
    showStatus();
    return { topic: item.topic, payload: item.payload, qos: 1, retain: false };
}
q.push(item);
if (q.length > MAX) {
    q.splice(0, q.length - MAX);      // descarta as mais antigas
    node.warn("Buffer cheio (" + MAX + "). Descartando mensagens mais antigas.");
}
setQ(q);
if (isOnline()) startFlush();          // online, mas ainda havia pendências: mantém a ordem
showStatus();
return null;

// GET /edge/status  -> diagnóstico LOCAL do gateway (não é a API da nuvem)
msg.payload = {
    mqtt_online: flow.get("mqtt_online") === true,
    forced_offline: flow.get("force_offline") === true,
    buffer_size: (flow.get("sf_queue", env.get("BUFFER_STORE") || "file") || []).length,
    simulate: env.get("SIMULATE") === "true",
    last_telemetry: flow.get("last_telemetry") || null
};
msg.headers = { "Content-Type": "application/json" };
msg.statusCode = 200;
return msg;
